const confirmMakeOwner = (makeOwner: (id: string) => Promise<void>, showToast: (options: {title: string, type: string}) => void) => {
    // Show confirmation modal
    try {
        await makeOwner(user.id);
        showToast({
            title: 'Ownership transferred',
            type: 'success'
        });
    } catch (e) {
        // Handle error
    }
};

