        </div>
    );
};

export const OffersIndexModal: React.FC<{defaultTab?: string}> = ({defaultTab}) => {
    const modal = useModal();
    const {updateRoute} = useRouting();
    const {data: {offers: allOffers = []} = {}, isFetching: isFetchingOffers} = useBrowseOffers();
    const {data: {tiers: allTiers} = {}} = useBrowseTiers();
    const signupOffers = allOffers.filter(offer => offer.redemption_type === 'signup');
    const [selectedTab, setSelectedTab] = useState(defaultTab || 'signup');
    const [statusFilter, setStatusFilter] = useState<'active' | 'archived'>('active');

    const {sortingState, setSortingState} = useSortingState();
    const offersSorting = sortingState?.find(sorting => sorting.type === 'offers');

    const sortOption = offersSorting?.option || 'date-added';
    const sortDirection = offersSorting?.direction || 'desc';

    const handleOfferEdit = (id:string) => {
        // TODO: implement
        sessionStorage.setItem('editOfferPageSource', 'offersIndex');
        updateRoute(`offers/edit/${id}`);
    };

    const filteredOffers = getFilteredOffers(signupOffers, allTiers, statusFilter);
    const sortedOffers = getSortedOffers(filteredOffers, sortOption, sortDirection);

    const handleSortChange = (selectedOption: string) => {
        setSortingState?.([{
            type: 'offers',
            option: selectedOption,
            direction: sortDirection
        }]);
    };

    const handleDirectionChange = () => {
        const newDirection = sortDirection === 'asc' ? 'desc' : 'asc';
        setSortingState?.([{
            type: 'offers',
            option: sortOption,
            direction: newDirection
        }]);
    };

    const buttons: ButtonProps[] = [
        {
            key: 'cancel-modal',
            label: 'Close',
            onClick: () => {
                modal.remove();
                updateRoute('offers');
            }
        },
        ...(selectedTab === 'signup' ? [{
            key: 'new-offer',
            icon: 'add',
            label: 'New offer',
            color: 'green' as const,
            onClick: () => {
                if (getPaidActiveTiers(allTiers || []).length === 0) {
                    showToast({
                        type: 'info',
                        title: 'You must have an active tier to create an offer.'
                    });
                } else {
                    updateRoute('offers/new');
                }
            }
        }] : [])
    ];

    const listLayoutOutput = getOfferListLayout(sortedOffers, allTiers);

    return <Modal
        afterClose={() => {
            updateRoute('offers');
        }}
        animate={false}
        backDropClick={false}
        cancelLabel=''
        footer={false}
        height='full'
        size='lg'
        testId='offers-modal'
        title='Offers'
        topRightContent={<ButtonGroup buttons={buttons} />}
        width={1140}
    >
        <div className='flex h-full flex-col pt-8'>
            <header>
                <TabView
                    selectedTab={selectedTab}
                    tabs={[
                        {id: 'signup', title: 'Signup'},
                        {id: 'retention', title: 'Retention'}
                    ]}
                    topRightContent={
                        selectedTab === 'signup' && sortedOffers.length > 0 ?
                            <div className='flex items-center'>
                                <span className='w-[220px] px-5 text-xs uppercase text-grey-700'>Terms</span>
                                <span className='w-[220px] px-5 text-xs uppercase text-grey-700'>Price</span>
                                <span className='w-[220px] px-5 text-xs uppercase text-grey-700'>Redemptions</span>
                                <span className='flex w-[80px] items-center justify-end'>
                                    <OffersFilterPopover
                                        setStatusFilter={setStatusFilter}
                                        sortDirection={sortDirection}
                                        sortOption={sortOption}
                                        statusFilter={statusFilter}
                                        onDirectionChange={handleDirectionChange}
                                        onSortChange={handleSortChange}
                                    />
                                </span>
                            </div> :
                            selectedTab === 'signup' ?
                                <div className='flex items-center'>
                                    <OffersFilterPopover
                                        setStatusFilter={setStatusFilter}
                                        sortDirection={sortDirection}
                                        sortOption={sortOption}
                                        statusFilter={statusFilter}
                                        onDirectionChange={handleDirectionChange}
                                        onSortChange={handleSortChange}
                                    />
                                </div> :
                                selectedTab === 'retention' ?
                                    <div className='flex items-center pt-[3px]'>
                                        <span className='w-[220px] px-5 text-xs uppercase text-grey-700'>Terms</span>
                                        <span className='w-[220px] px-5 text-xs uppercase text-grey-700'>Redemptions</span>
                                        <span className='w-[220px] px-5 text-xs uppercase text-grey-700'>Status</span>
                                        <span className='w-[80px]'></span>
                                    </div> :
                                    null
                    }
                    onTabChange={(tab) => {
                        setSelectedTab(tab);
                        updateRoute(tab === 'retention' ? 'offers/edit/retention' : 'offers/edit');
                    }}
                />
            </header>
            {selectedTab === 'signup' && statusFilter === 'active' && sortedOffers.length === 0 && !isFetchingOffers ?
                <EmptyState
                    buttonAction={() => updateRoute('offers/new')}
                    buttonLabel='Create an offer'
                    description='Grow your audience with discounts or free trials.'
                /> :
                null
            }
            {selectedTab === 'signup' && statusFilter === 'archived' && sortedOffers.length === 0 && !isFetchingOffers ?
                <EmptyState
                    buttonAction={() => setStatusFilter('active')}
                    buttonLabel='Back to active'
                    description='All archived offers will be shown here.'
                /> :
                null
            }
            {selectedTab === 'retention' && <OffersRetention />}
            {selectedTab === 'signup' && listLayoutOutput}
        </div>
    </Modal>;
};
