                <col className='w-[220px]' />
                <col className='w-[220px]' />
                <col className='w-[220px]' />
                <col className='w-[80px]' />
            </colgroup>
            {filteredOffers.map((offer) => renderOfferRow(offer, allTiers))}
        </table>
    </div>;

    const handleSortChange = (selectedOption: string) => {
        setSortingState?.([{
