            return multiplier * ((offer1.created_at ? new Date(offer1.created_at).getTime() : 0) - (offer2.created_at ? new Date(offer2.created_at).getTime() : 0));
        }
    });
};

const OfferRow: React.FC<{offer: any, allTiers: any[], selectedTab: string, handleOfferEdit: (id: string) => void}> = ({offer, allTiers, selectedTab, handleOfferEdit}) => {
