        let uploadResponse;
        let responseUrl;

        try {
            uploadResponse = JSON.parse(response);
        } catch (error) {
            if (!(error instanceof SyntaxError)) {
                throw error;
            }
        }

        if (uploadResponse) {
            const resource = uploadResponse[fileTypes['image'].resourceName];
            if (resource && Array.isArray(resource) && resource[0]) {
                responseUrl = resource[0].url;
            }
        }

        return {
            url: responseUrl,
            fileName: file.name
        };
    } catch (error) {
        console.error(error); 

        let message = error.payload?.errors?.[0]?.message || '';
        let context = error.payload?.errors?.[0]?.context || '';

        if (!message) {
            message = error.message;
        }

        const errorResult = {
            message,
            context,
            fileName: file.name
        };

        throw errorResult;
    }
}

