    const now = new Date();
    const monthsBack = 12;
    let startDate = new Date(now.getTime() - (monthsBack * 30 * 24 * 60 * 60 * 1000));

    // If content has a publication date, ensure views only happen after publication
    if (publishedAt) {
        const pubDate = new Date(publishedAt);
        if (pubDate > startDate) {
