            } else {
                hasMore = false;
            }
        }
    } else {
        const data = await fetchReplies({api, comment, afterReplyId, limit: limit as number || 100, isReply});
        allComments = data.comments;
    }

    return {
        comments: state.comments.map((c) => {
            if (c.id === comment.id) {
                return {
                    ...comment,
                    replies: [...comment.replies, ...allComments]
                };
