    return fonts.map((font) => ({
        label: font.name,
        value: font.name,
        creator: font.creator,
        className: getFontClassName(font.name),
    })).unshift({
        label: defaultFont,
        value: defaultFont,
        creator: defaultCreator,
        className: 'font-sans font-normal',
    });
};

