    if (dataRoot.site.accent_color) {
        const accentColor = escapeExpression(dataRoot.site.accent_color);
        const styleTag = `<style>:root {--ghost-accent-color: ${accentColor};}</style>`;
        return styleTag;
    }

    return '';
}

