}

function validateFileExists(fileName) {
  // Check if the file exists
  if (!fs.existsSync(fileName)) {
    return false;
  }
  return true;
}

function validateLineNumber(lineNumber) {
  // Sanitize lineNumber to prevent malicious use on win32
  // via: https://github.com/nodejs/node/blob/c3bb4b1aa5e907d489619fb43d233c3336bfc03d/lib/child_process.js#L333
  // and it should be a positive integer
  if (!(Number.isInteger(lineNumber) && lineNumber > 0)) {
    return false;
  }
  return true;
}

function validateColNumber(colNumber) {
  // colNumber is optional, but should be a positive integer too
  // default is 1
  if (!(Number.isInteger(colNumber) && colNumber > 0)) {
    return 1;
  }
  return colNumber;
}

function validateFileName(fileName) {
