													node,
												),
												"Global turned off in directive should not be identified as a global reference",
											);
										}
									});

									return { Identifier: spy };
								},
							},
						},
					},
				},
				rules: { "test/checker": "error" },
			};

			linter.verify(code, config);
			assert(spy && spy.called, "Spy was not called.");
