            {
              enum: ["functions"],
            },
          ],
          minItems: 0,
          maxItems: 1,
        },
        {
          type: "array",
          items: [
            {
              enum: ["all"],
            },
            {
              type: "object",
              properties: {
                conditionalAssign: { type: "boolean" },
                ternaryOperandBinaryExpressions: {
                  type: "boolean",
                },
                nestedBinaryExpressions: { type: "boolean" },
                returnAssign: { type: "boolean" },
                ignoreJSX: {
