                for (let i = 0; i < listenerCallQueue.length; i++) {
                    const nodeInfo = listenerCallQueue[i];

                    if (!ignoredNodeFirstTokens.has(sourceCode.getFirstToken(nodeInfo.node))) {
                        nodeInfo.listener(nodeInfo.node);
