    const lastToken = sourceCode.getLastToken(node);

    if (options.VariableDeclarator[node.kind] === "first") {
      if (node.declarations.length > 1) {
        addElementListIndent(
          node.declarations,
          firstToken,
          lastToken,
          "first",
