    const tokens = sourceCode.tokensAndComments;

    for (let i = 0; i < tokens.length; i++) {
      const token = tokens[i];

      if (!this.firstTokensByLineNumber.has(token.loc.start.line)) {
        this.firstTokensByLineNumber.set(token.loc.start.line, token);
      }
      if (
        !this.firstTokensByLineNumber.has(token.loc.end.line) &&
        sourceCode.text
          .slice(
            token.range[1] - token.loc.end.column,
            token.range[1],
          )
          .trim()
      ) {
        this.firstTokensByLineNumber.set(token.loc.end.line, token);
      }
    }
  }

  /**
   * Gets the first token on a given token's line
   * @param {Token|ASTNode} token a node or token
   * @returns {Token} The first token on the given line
   */
  getFirstTokenOfLine(token) {
    return this.firstTokensByLineNumber.get(token.loc.start.line);
  }

  /**
   * Determines whether a token is the first token in its line
   * @param {Token} token The token
   * @returns {boolean} `true` if the token is the first on its line
   */
  isFirstTokenOfLine(token) {
    return this.getFirstTokenOfLine(token) === token;
  }

  /**
   * Get the actual indent of a token
   * @param {Token} token Token to examine. This should be the first token on its line.
   * @returns {string} The indentation characters that precede the token
   */
  getTokenIndent(token) {
    return this.sourceCode.text.slice(
      token.range[0] - token.loc.start.column,
      token.range[0],
    );
  }
}

/**
 * A class to store information on desired offsets of tokens from each other
 */
class OffsetStorage {
  /**
   * @param {TokenInfo} tokenInfo a TokenInfo instance
   * @param {number} indentSize The desired size of each indentation level
   * @param {string} indentType The indentation character
   * @param {number} maxIndex The maximum end index of any token
   */
  constructor(tokenInfo, indentSize, indentType, maxIndex) {
    this._tokenInfo = tokenInfo;
    this._indentSize = indentSize;
    this._indentType = indentType;

    this._indexMap = new IndexMap(maxIndex);
    this._indexMap.insert(0, { offset: 0, from: null, force: false });

    this._lockedFirstTokens = new WeakMap();
    this._desiredIndentCache = new WeakMap();
    this._ignoredTokens = new WeakSet();
  }

  _getOffsetDescriptor(token) {
    return this._indexMap.findLastNotAfter(token.range[0]);
  }

  /**
   * Sets the offset column of token B to match the offset column of token A.
   * - **WARNING**: This matches a *column*, even if baseToken is not the first token on its line. In
   * most cases, `setDesiredOffset` should be used instead.
   * @param {Token} baseToken The first token
   * @param {Token} offsetToken The second token, whose offset should be matched to the first token
   * @returns {void}
   */
  matchOffsetOf(baseToken, offsetToken) {
    this._lockedFirstTokens.set(offsetToken, baseToken);
  }

  /**
   * Sets the desired offset of a token.
   *
   * This uses a line-based offset collapsing behavior to handle tokens on the same line.
   * For example, consider the following two cases:
   *
   * (
   *     [
   *         bar
   *     ]
   * )
   *
   * ([
   *     bar
   * ])
   *
   * Based on the first case, it's clear that the `bar` token needs to have an offset of 1 indent level (4 spaces) from
   * the `[` token, and the `[` token has to have an offset of 1 indent level from the `(` token. Since the `(` token is
   * the first on its line (with an indent of 0 spaces), the `bar` token needs to be offset by 2 indent levels (8 spaces)
   * from the start of its line.
   *
   * However, in the second case `bar` should only be indented by 4 spaces. This is because the offset of 1 indent level
   * between the `(` and the `[` tokens gets "collapsed" because the two tokens are on the same line. As a result, the
   * `(` token is mapped to the `[` token with an offset of 0, and the rule correctly decides that `bar` should be indented
   * by 1 indent level from the start of the line.
   *
   * This is useful because rule listeners can usually just call `setDesiredOffset` for all the tokens in the node,
   * without needing to check which lines those tokens are on.
   *
   * Note that since collapsing only occurs when two tokens are on the same line, there are a few cases where non-intuitive
   * behavior can occur. For example, consider the following cases:
   *
   * foo(
   * ).
   *     bar(
   *         baz
   *     )
   *
   * foo(
   * ).bar(
   *     baz
   * )
   *
   * Based on the first example, it would seem that `bar` should be offset by 1 indent level from `foo`, and `baz`
   * should be offset by 1 indent level from `bar`. However, this is not correct, because it would result in `baz`
   * being indented by 2 indent levels in the second case (since `foo`, `bar`, and `baz` are all on separate lines, no
   * collapsing would occur).
   *
   * Instead, the correct way would be to offset `baz` by 1 level from `bar`, offset `bar` by 1 level from the `)`, and
   * offset the `)` by 0 levels from `foo`. This ensures that the offset between `bar` and the `)` are correctly collapsed
   * in the second case.
   * @param {Token} token The token
   * @param {Token} fromToken The token that `token` should be offset from
   * @param {number} offset The desired indent level
   * @returns {void}
   */
  setDesiredOffset(token, fromToken, offset) {
    return this.setDesiredOffsets(token.range, fromToken, offset);
  }

  /**
   * Sets the desired offset of all tokens in a range
   * It's common for node listeners in this file to need to apply the same offset to a large, contiguous range of tokens.
   * Moreover, the offset of any given token is usually updated multiple times (roughly once for each node that contains
   * it). This means that the offset of each token is updated O(AST depth) times.
   * It would not be performant to store and update the offsets for each token independently, because the rule would end
   * up having a time complexity of O(number of tokens * AST depth), which is quite slow for large files.
   *
   * Instead, the offset tree is represented as a collection of contiguous offset ranges in a file. For example, the following
   * list could represent the state of the offset tree at a given point:
   *
   * - Tokens starting in the interval [0, 15) are aligned with the beginning of the file
   * - Tokens starting in the interval [15, 30) are offset by 1 indent level from the `bar` token
   * - Tokens starting in the interval [30, 43) are offset by 1 indent level from the `foo` token
   * - Tokens starting in the interval [43, 820) are offset by 2 indent levels from the `bar` token
   * - Tokens starting in the interval [820, ∞) are offset by 1 indent level from the `baz` token
   *
   * The `setDesiredOffsets` methods inserts ranges like the ones above. The third line above would be inserted by using:
   * `setDesiredOffsets([30, 43], fooToken, 1);`
   * @param {[number, number]} range A [start, end] pair. All tokens with range[0] <= token.start < range[1] will have the offset applied.
   * @param {Token} fromToken The token that this is offset from
   * @param {number} offset The desired indent level
   * @param {boolean} force `true` if this offset should not use the normal collapsing behavior. This should almost always be false.
   * @returns {void}
   */
  setDesiredOffsets(range, fromToken, offset, force) {
    const descriptorToInsert = { offset, from: fromToken, force };

    const descriptorAfterRange = this._indexMap.findLastNotAfter(range[1]);

    const fromTokenIsInRange =
      fromToken &&
      fromToken.range[0] >= range[0] &&
      fromToken.range[1] <= range[1];
    const fromTokenDescriptor =
      fromTokenIsInRange && this._getOffsetDescriptor(fromToken);

    this._indexMap.deleteRange(range[0] + 1, range[1]);

    this._indexMap.insert(range[0], descriptorToInsert);

    if (fromTokenIsInRange) {
      this._indexMap.insert(fromToken.range[0], fromTokenDescriptor);
      this._indexMap.insert(fromToken.range[1], descriptorToInsert);
    }

    this._indexMap.insert(range[1], descriptorAfterRange);
  }

  /**
   * Gets the desired indent of a token
   * @param {Token} token The token
   * @returns {string} The desired indent of the token
   */
  getDesiredIndent(token) {
    if (!this._desiredIndentCache.has(token)) {
      if (this._ignoredTokens.has(token)) {
        this._desiredIndentCache.set(
          token,
          this._tokenInfo.getTokenIndent(token),
        );
      } else if (this._lockedFirstTokens.has(token)) {
        const firstToken = this._lockedFirstTokens.get(token);

        this._desiredIndentCache.set(
          token,
          this.getDesiredIndent(
            this._tokenInfo.getFirstTokenOfLine(firstToken),
          ) +
            this._indentType.repeat(
              firstToken.loc.start.column -
                this._tokenInfo.getFirstTokenOfLine(firstToken)
                  .loc.start.column,
            ),
        );
      } else {
        const offsetInfo = this._getOffsetDescriptor(token);
        const offset =
          offsetInfo.from &&
          offsetInfo.from.loc.start.line === token.loc.start.line &&
          !/^\s*?\n/u.test(token.value) &&
          !offsetInfo.force
            ? 0
            : offsetInfo.offset * this._indentSize;

        this._desiredIndentCache.set(
          token,
          (offsetInfo.from
            ? this.getDesiredIndent(offsetInfo.from)
            : "") + this._indentType.repeat(offset),
        );
      }
    }
    return this._desiredIndentCache.get(token);
  }

  /**
   * Ignores a token, preventing it from being reported.
   * @param {Token} token The token
   * @returns {void}
   */
  ignoreToken(token) {
    if (this._tokenInfo.isFirstTokenOfLine(token)) {
      this._ignoredTokens.add(token);
    }
  }

  /**
   * Gets the first token that the given token's indentation is dependent on
   * @param {Token} token The token
   * @returns {Token} The token that the given token depends on, or `null` if the given token is at the top level
   */
  getFirstDependency(token) {
    return this._getOffsetDescriptor(token).from;
  }
}

const ELEMENT_LIST_SCHEMA = {
  oneOf: [
    {
      type: "integer",
      minimum: 0,
    },
    {
      enum: ["first", "off"],
    },
  ],
};

/** @type {import('../types').Rule.RuleModule} */
module.exports = {
  meta: {
    deprecated: {
      message: "Formatting rules are being moved out of ESLint core.",
      url: "https://eslint.org/blog/2023/10/deprecating-formatting-rules/",
      deprecatedSince: "8.53.0",
      availableUntil: "11.0.0",
      replacedBy: [
        {
          message:
            "ESLint Stylistic now maintains deprecated stylistic core rules.",
          url: "https://eslint.style/guide/migration",
          plugin: {
            name: "@stylistic/eslint-plugin",
            url: "https://eslint.style",
          },
          rule: {
            name: "indent",
            url: "https://eslint.style/rules/indent",
          },
        },
      ],
    },
    type: "layout",

    docs: {
      description: "Enforce consistent indentation",
      recommended: false,
      url: "https://eslint.org/docs/latest/rules/indent",
    },

    fixable: "whitespace",

    schema: [
      {
        oneOf: [
          {
            enum: ["tab"],
          },
          {
            type: "integer",
            minimum: 0,
          },
        ],
      },
      {
        type: "object",
        properties: {
          SwitchCase: {
            type: "integer",
            minimum: 0,
            default: 0,
          },
          VariableDeclarator: {
            oneOf: [
              ELEMENT_LIST_SCHEMA,
              {
                type: "object",
                properties: {
                  var: ELEMENT_LIST_SCHEMA,
                  let: ELEMENT_LIST_SCHEMA,
                  const: ELEMENT_LIST_SCHEMA,
                },
                additionalProperties: false,
              },
            ],
          },
          outerIIFEBody: {
            oneOf: [
              {
                type: "integer",
                minimum: 0,
              },
              {
                enum: ["off"],
              },
            ],
          },
          MemberExpression: {
            oneOf: [
              {
                type: "integer",
                minimum: 0,
              },
              {
                enum: ["off"],
              },
            ],
          },
          FunctionDeclaration: {
            type: "object",
            properties: {
              parameters: ELEMENT_LIST_SCHEMA,
              body: {
                type: "integer",
                minimum: 0,
              },
            },
            additionalProperties: false,
          },
          FunctionExpression: {
            type: "object",
            properties: {
              parameters: ELEMENT_LIST_SCHEMA,
              body: {
                type: "integer",
                minimum: 0,
              },
            },
            additionalProperties: false,
          },
          StaticBlock: {
            type: "object",
            properties: {
              body: {
                type: "integer",
                minimum: 0,
              },
            },
            additionalProperties: false,
          },
          CallExpression: {
            type: "object",
            properties: {
              arguments: ELEMENT_LIST_SCHEMA,
            },
            additionalProperties: false,
          },
          ArrayExpression: ELEMENT_LIST_SCHEMA,
          ObjectExpression: ELEMENT_LIST_SCHEMA,
          ImportDeclaration: ELEMENT_LIST_SCHEMA,
          flatTernaryExpressions: {
            type: "boolean",
            default: false,
          },
          offsetTernaryExpressions: {
            type: "boolean",
            default: false,
