		it("should retrieve all tokens and comments after a node with includeComments option", () => {
			check(
				extractTokensAfter(store, VariableDeclarator.id, {
					includeComments: true,
				}),
				[
					"B",
					"=",
					"C",
					"a",
					"D",
					"*",
					"b",
					"E",
					"F",
					"call",
					"(",
					")",
					";",
					"Z",
