          outerIIFEBody: {
            type: "integer",
            minimum: 0,
          },
          MemberExpression: {
            type: "integer",
            minimum: 0,
          },
          FunctionDeclaration: {
            type: "object",
            properties: {
              parameters: {
                oneOf: [
                  {
                    type: "integer",
                    minimum: 0,
                  },
