                    enum: ["first"],
                  },
                ],
              },
              body: {
                type: "integer",
                minimum: 0,
              },
            },
          },
          FunctionExpression: {
            type: "object",
            properties: {
              parameters: {
                oneOf: [
                  {
                    type: "integer",
                    minimum: 0,
                  },
                  {
                    enum: ["first"],
                  },
                ],
              },
              body: {
                type: "integer",
                minimum: 0,
              },
            },
          },
          CallExpression: {
            type: "object",
            properties: {
              parameters: {
