          node,
          lastLineIndent,
          endIndent.space,
          endIndent.tab,
          {
            line: lastToken.loc.start.line,
            column: lastToken.loc.start.column,
          },
          true,
        );
      }
    }

    function checkLastReturnStatementLineIndent(node, firstLineIndent) {
