        "IfStatement",
        "WhileStatement",
        "ForStatement",
        "ForInStatement",
        "ForOfStatement",
        "DoWhileStatement",
        "ClassDeclaration",
        "TryStatement",
      ];

      if (
        node.parent &&
        statementsWithProperties.includes(node.parent.type) &&
        isNodeBodyBlock(node)
