 * @returns {VerifyOptions&ProcessorOptions&FixOptions} The normalized options.
 */
_normalizeVerifyAndFixOptions(filenameOrOptions) {
    return typeof filenameOrOptions === "string"
        ? { filename: filenameOrOptions }
        : filenameOrOptions || {};
