        } else {
            const deps = Object.keys(dependency.deps);
            for (let i = 0; i < deps.length; ++i) {
                const dep = deps[i];
                const version = dependency.deps[dep];

                if (!this._registrations[dep]) {
                    return new Error('Plugin ' + dependency.plugin + ' missing dependency ' + dep);
