  if (!clientSideValidateProp(element.schema, modalState.value)) {
    setModalState(state => ({
      ...(state as any),
      forceValidation: true,
    }))
    return
  }
  previewPropsOnChange(modalState.value, element)
  setModalState('closed')
}

