      isRequired={props.isRequired}
      items={field.options}
      onChange={key => handleSelectionChange(key, props)}
      value={selectedKey}
      textValue={field.options.find(item => item.value === selectedKey)?.label || ''}
    >
      {item => <Item key={item.value}>{item.label}</Item>}
    </SegmentedControl>
  )

