  CLI.prototype.serve = function (target_path, port, opts, commander, cb) {
    const that = this;
    let servePort = process.env.PM2_SERVE_PORT || port || 8080;
    let servePath = path.resolve(process.env.PM2_SERVE_PATH || target_path || '.');

