   *
   * @param {Object} config The configuration.
   * @returns {String} The generated URI.
   */
  databaseConnectionUri(config) {
    let uri = config.protocol + '://' + config.user + ':' + config.password + '@' + config.host;
    if (config.port) {
      uri += ':' + config.port;
