const isPermissionEnabledForRole = (permission, role) => {
  // Check if the permission is enabled by default
  const defaultPermission = DEFAULT_PERMISSIONS.find(defaultPerm =>
    (defaultPerm.action === null || permission.action === defaultPerm.action) &&
    (defaultPerm.controller === null || permission.controller === defaultPerm.controller) &&
    (defaultPerm.type === null || permission.type === defaultPerm.type) &&
    (defaultPerm.roleType === null || role.type === defaultPerm.roleType)
  );

  // If the permission is enabled by default, return true
  if (defaultPermission) {
    return true;
  }

  // Otherwise, return the enabled value of the permission
  return _.toNumber(permission.enabled) === 1;
