          limit: 'Int',
          start: 'Int',
          where: 'JSON',
          ...(resolver.args || {}),
        },
        type: connectionFields.values,
      },
    },
    resolvers: getConnectionResolvers(fields, model, name, resolver),
  };
};

module.exports = {
  formatModelConnectionsGQL,
};
