      resolvers: {
        Morph: {
          __resolveType(obj) {
            return obj.kind || obj.__contentType || null;
          },
        },
      },
    };
  }

  return {
    definition: '',
    resolvers: {},
  };
};

const addInput = () => {
  // Add input type
  return `
    input InputID { id: ID!}
  `;
};

