    if (elementName === 'backButton' && backButtonDestination && currentStep === 'upload') {
      return !isEmpty(filesToUpload);
    }

    if (elementName === 'backButton' && backButtonDestination && currentStep === 'browse') {
      return !isEmpty(filesToUpload);
    }

    return false;
